from (values
('mcq', 1, 1, 'طاقة التنشيط هي الفرق بين طاقة قمة المنحنى (المعقد المنشط) وطاقة المتفاعلات؛ فالفرق بين قمة المنحنى المحفز ومستوى المتفاعلات هو طاقة تنشيط التفاعل المحفز (170 − 100 = 70 kJ).', '["ΔH هو الفرق بين مستوى النواتج ومستوى المتفاعلات، ولا يتعلق بالقمة.","","النقص في طاقة التنشيط هو الفرق بين قمتي المنحنيين، لا بين القمة ومستوى المتفاعلات.","طاقة تنشيط التفاعل غير المحفز تُقاس من قمة المنحنى غير المحفز (الأعلى) لا من قمة المنحنى المحفز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-04T12:15:46.058Z"}'::jsonb),
('mcq', 2, 0, 'طاقة التنشيط = طاقة القمة − طاقة المتفاعلات = 250 kJ − 100 kJ = 150 kJ.', '["","هذه طاقة قمة المنحنى (المعقد المنشط)، وطاقة التنشيط هي الفرق بين القمة وطاقة المتفاعلات.","هذا الفرق بين القمة وطاقة النواتج (250 − 40)، وهو طاقة تنشيط التفاعل العكسي.","هذا الفرق بين طاقتي المتفاعلات والنواتج، وهو مقدار ΔH لا طاقة التنشيط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-04T12:15:46.058Z"}'::jsonb),
('mcq', 3, 3, 'طاقة التنشيط غير المحفز = 250 − 100 = 150 kJ، والمحفز = 170 − 100 = 70 kJ، فالنقص = 150 − 70 = 80 kJ (ويساوي أيضًا الفرق بين القمتين 250 − 170).', '["هذه طاقة التنشيط للتفاعل المحفز نفسه (170 − 100)، لا مقدار النقص.","هذا مقدار ΔH (100 − 40)، ولا علاقة له بالنقص في طاقة التنشيط.","هذا الفرق بين قمة المسار المحفز وطاقة النواتج (170 − 40).",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (70%)"}],"at":"2026-11-04T12:15:46.058Z"}'::jsonb),
('mcq', 4, 2, 'طاقة التنشيط = طاقة القمة − طاقة المتفاعلات: بوجود A تساوي 190 − 100 = 90 kJ، وبوجود B تساوي 150 − 100 = 50 kJ. وكلما قلت طاقة التنشيط زاد عدد التصادمات التي تمتلك الطاقة الكافية، فيكون التفاعل بوجود المحفز B أسرع، وطاقة تنشيطه 50 kJ.', '["طاقة التنشيط بوجود A (90 kJ) أكبر منها بوجود B (50 kJ)، فالتفاعل بوجود A أبطأ.","الـ 150 kJ هي طاقة قمة المسار B (المعقد المنشط)، لا الفرق بينها وبين طاقة المتفاعلات.","","الـ 110 kJ هي الفرق بين قمة المسار B ومستوى النواتج (150 − 40)، لا بينها وبين مستوى المتفاعلات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-04T12:15:46.058Z"}'::jsonb),
('mcq', 5, 0, 'ΔH = طاقة النواتج − طاقة المتفاعلات = 120 − 50 = +70 kJ (ماص). وطاقة تنشيط التفاعل المحفز = 160 − 50 = 110 kJ.', '["","طاقة النواتج (120 kJ) أكبر من طاقة المتفاعلات (50 kJ)، فالتفاعل ماص وΔH موجبة.","الـ 160 kJ هي طاقة قمة المسار المحفز، لا الفرق بينها وبين طاقة المتفاعلات.","الـ 180 kJ هي طاقة تنشيط التفاعل غير المحفز (230 − 50)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (55%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb),
('mcq', 6, 3, 'المحفز يوفر مسارًا بطاقة تنشيط أقل، فتنخفض قمة المنحنى (طاقة المعقد المنشط)، أما مستويا المتفاعلات والنواتج والفرق بينهما (ΔH) فتبقى كما هي.', '["المتفاعلات واحدة في المسارين، فمستوى طاقتها واحد.","المحفز لا يغير النواتج، فمستوى طاقتها واحد في المسارين.","هذا الفرق هو ΔH، ولا يغيره المحفز لأن المتفاعلات والنواتج نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb),
('mcq', 7, 2, 'المعقد المنشط يقع عند قمة المنحنى، وقمة المسار (2) عند 170 kJ، فطاقة المعقد المنشط فيه 170 kJ.', '["هذه طاقة التنشيط في المسار (2) (170 − 100)، لا طاقة المعقد المنشط نفسه.","هذه طاقة قمة المسار (1).","","هذا الفرق بين قمة المسار (2) وطاقة النواتج (170 − 40)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) طاقة التنشيط غير المحفز = 250 − 100 = 150 kJ، وطاقة التنشيط المحفز = 170 − 100 = 70 kJ. (ب) ΔH = 40 − 100 = −60 kJ في المسارين، فالتفاعل طارد للطاقة. (ج) المحفز قلل طاقة التنشيط بمقدار 80 kJ، فيمتلك عدد أكبر من التصادمات الطاقة الكافية فيتكون الناتج بسرعة أكبر، لكنه لم يغير طاقة المتفاعلات ولا النواتج ولا ΔH.', '["Ea غير محفز = 150 kJ","Ea محفز = 70 kJ","ΔH = −60 kJ للمسارين","المحفز يقلل Ea ولا يغير ΔH"]'::jsonb, '["Ea(غير محفز) = 250 − 100 = 150 kJ","Ea(محفز) = 170 − 100 = 70 kJ","ΔH = 40 − 100 = −60 kJ","النقص في Ea = 150 − 70 = 80 kJ"]'::jsonb, '[{"element":"طاقتا التنشيط","marks":1},{"element":"ΔH للمسارين","marks":1},{"element":"أثر المحفز في طاقة التنشيط والسرعة","marks":1},{"element":"عدم تغير ΔH","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحسب طاقتي التنشيط وΔH صحيحة ويستنتج أثر المحفز كاملًا"},{"level":"2–3 درجات","description":"يحسب بعض القيم صحيحة أو يستنتج دون حساب كامل"},{"level":"1 درجة","description":"يذكر أن المحفز يقلل طاقة التنشيط دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["قراءة طاقة القمة على أنها طاقة التنشيط","كتابة ΔH موجبة لتفاعل طارد","القول إن المحفز يغير ΔH"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القول خطأ. الطاقة الممتصة (ΔH) هي الفرق بين طاقة النواتج وطاقة المتفاعلات: 120 − 50 = +70 kJ، وهي واحدة في المسارين لأنهما يبدآن وينتهيان عند المستويين أنفسهما. أما انخفاض القمة فيعني انخفاض طاقة التنشيط: من 230 − 50 = 180 kJ دون محفز إلى 160 − 50 = 110 kJ بمحفز؛ فالمحفز يسرّع التفاعل ولا يغير كمية الطاقة الممتصة.', '["الحكم بخطأ القول","ΔH = +70 kJ في المسارين","انخفاض القمة يعني نقص طاقة التنشيط من 180 kJ إلى 110 kJ"]'::jsonb, '["ΔH = 120 − 50 = +70 kJ","Ea(غير محفز) = 230 − 50 = 180 kJ","Ea(محفز) = 160 − 50 = 110 kJ"]'::jsonb, '[{"element":"الحكم بخطأ القول","marks":1},{"element":"إثبات ثبات ΔH بالقيم","marks":1},{"element":"تفسير انخفاض القمة بنقص طاقة التنشيط بالقيم","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يحكم صحيحًا ويثبت ثبات ΔH وينسب انخفاض القمة إلى طاقة التنشيط بالقيم"},{"level":"2 درجتان","description":"يحكم صحيحًا ويعلل دون قيم، أو بقيم لعنصر واحد"},{"level":"1 درجة","description":"يحكم بخطأ القول دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على أن المحفز يغير ΔH","حساب ΔH من القمة","الخلط بين طاقة التنشيط والطاقة الممتصة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) طاقة المعقد المنشط دون محفز = 80 + 120 = 200 kJ، وبمحفز = 80 + 50 = 130 kJ، وΔH = 20 − 80 = −60 kJ. (ب) يظهر في المخطط محور رأسي للطاقة ومحور أفقي لسير التفاعل؛ ويبدأ المساران من مستوى المتفاعلات 80 kJ، ويرتفع المسار غير المحفز إلى قمة عند 200 kJ والمسار المحفز إلى قمة أخفض عند 130 kJ، ثم ينتهيان عند مستوى النواتج نفسه 20 kJ. (ج) طاقة التنشيط عقبة يجب تخطيها كالحاجز أمام الحصان؛ فالحاجز المنخفض (طاقة تنشيط 50 kJ) يحتاج إلى طاقة أقل لاجتيازه، فيتمكن عدد أكبر من الجسيمات المتصادمة من تجاوزه في وحدة الزمن، فيتكون الناتج بسرعة أكبر.', '["طاقتا المعقد المنشط 200 kJ و130 kJ","ΔH = −60 kJ","وصف صحيح للمخطط: بداية ونهاية واحدة وقمتان مختلفتان","تفسير التشبيه بعدد الجسيمات القادرة على تجاوز العقبة"]'::jsonb, '["قمة غير محفز = 80 + 120 = 200 kJ","قمة محفز = 80 + 50 = 130 kJ","ΔH = 20 − 80 = −60 kJ"]'::jsonb, '[{"element":"طاقتا المعقد المنشط","marks":1},{"element":"ΔH","marks":1},{"element":"وصف المخطط","marks":1},{"element":"تفسير التشبيه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحسب القيم الثلاث ويصف المخطط وصفًا صحيحًا ويفسر التشبيه"},{"level":"2–3 درجات","description":"يحسب القيم مع وصف ناقص أو تفسير ناقص للتشبيه"},{"level":"1 درجة","description":"يحسب قيمة واحدة صحيحة أو يصف المخطط فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["رسم المسارين بنهايتين مختلفتين","إضافة طاقة التنشيط إلى طاقة النواتج بدل المتفاعلات","جعل قمة المسار المحفز أعلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-11-04T12:15:46.059Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O12') and x.type = v.type and x.number = v.number
