select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'المحفز يزيد سرعة التفاعل بتقليل طاقة التنشيط، فيقصر زمن اكتماله، لكنه لا يُستهلك ولا يزيد عدد النواتج؛ فتبقى كمية النواتج عند اكتمال التفاعل كما هي.', '["المحفز يزيد سرعة التفاعل الكيميائي، فهي تتغير.","المحفز يزيد السرعة بتقليل طاقة التنشيط، فهي تتغير.","","زيادة السرعة تجعل التفاعل يكتمل في زمن أقصر، فالزمن يتغير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-04T12:15:46.060Z"}'::jsonb),
('mcq', 2, 3, 'MnO₂ محفز لتحلل H₂O₂، والمحفز لا يُستهلك في التفاعل، فيبقى بعد انتهائه بكميته نفسها؛ لذا يمكن استرجاعه واستعماله من جديد، فيُسرّع تحلل العينة الجديدة كما سرّع تحلل الأولى، دون أن يزيد كمية الأكسجين الناتجة.', '["المحفز لا يُستهلك في التفاعل؛ فيبقى قادرًا على تسريع التحلل في العينة الجديدة.","المحفز لا يزيد عدد النواتج؛ فكمية O₂ تحددها كمية H₂O₂ في العينة.","المحفز لا يتحول إلى نواتج، والأكسجين الناتج مصدره H₂O₂ لا MnO₂.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-04T12:15:46.060Z"}'::jsonb),
('mcq', 3, 0, 'كمية O₂ الكلية تحددها كمية H₂O₂ المتحللة، وهي واحدة في العينتين، والمحفز لا يزيد عدد النواتج؛ فيكون الحجم الكلي متساويًا، غير أن العينة ذات المحفز تبلغه في زمن أقصر.', '["","المحفز لا يزيد كمية النواتج؛ فكمية O₂ تحددها كمية H₂O₂.","المحفز لا يُستهلك ولا يستهلك النواتج.","المحفز لا يتحول إلى نواتج ولا يضيف إليها شيئًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.061Z"}'::jsonb),
('mcq', 4, 1, 'المحفز لا يعد ضمن المواد المتفاعلة أو الناتجة، لذا لا يُكتب في أيّ من طرفي المعادلة؛ والمعادلة الموزونة للتحلل هي 2H₂O₂(aq) → 2H₂O(l) + O₂(g).', '["كتابة المحفز ضمن المتفاعلات خطأ؛ فهو لا يُستهلك ولا يعد ضمن المواد المتفاعلة.","","كتابة المحفز ضمن النواتج خطأ؛ فهو لا يتكون من التفاعل.","المعادلة غير موزونة: ذرات الأكسجين 2 في الطرف الأيسر و3 في الأيمن."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-11-04T12:15:46.061Z"}'::jsonb),
('mcq', 5, 3, 'الإنزيم نوع من المحفزات يزيد سرعة التفاعل الكيميائي دون أن يُستهلك فيه؛ لذا يعود الجزيء نفسه ليحفز التفاعل مرات كثيرة، فتكفي كمية صغيرة منه لتحويل كمية كبيرة من المادة.', '["لو استُهلك كل جزيء إنزيم لاحتاجت الخلية كمية منه تكافئ المادة المتحولة؛ والإنزيم محفز لا يُستهلك.","الإنزيم لا يزيد كمية النواتج ولا يتحول إليها.","المحفز لا يعد ضمن المتفاعلات، ولا يلزم بكميات مكافئة لها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-11-04T12:15:46.061Z"}'::jsonb),
('mcq', 6, 1, 'تُستعمل المحفزات في الصناعة لإنتاج كمية أكبر من المنتج بسرعة كبيرة (أي في وحدة الزمن)، مما يقلل من تكلفته، ولأنها لا تُستهلك يمكن استعمالها مرارًا؛ لكنها لا تزيد كمية النواتج النهائية من الكمية نفسها من المتفاعلات.', '["المحفز لا يزيد عدد النواتج؛ وما يزداد هو كمية الإنتاج في وحدة الزمن.","","المحفز لا يُستهلك في التفاعل ولا يحل محل المتفاعلات.","المحفز لا يعد ضمن النواتج ولا يتحول إليها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-11-04T12:15:46.061Z"}'::jsonb),
('mcq', 7, 0, 'قصر زمن التفاعل من نحو 10 h إلى 40 s يدل على زيادة السرعة، وثبات كتلة MnO₂ (0.50 g) يدل على أنه لم يُستهلك، وتساوي حجم O₂ (48 mL) يدل على أنه لم يزد كمية النواتج.', '["","حجم O₂ الكلي 48 mL في التجربتين، فالمحفز لم يزد كميته.","كتلة MnO₂ بقيت 0.50 g قبل التفاعل وبعده، فلم يُستهلك.","التجربة (1) أنتجت 48 mL دون محفز، لكن في زمن أطول بكثير."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-04T12:15:46.061Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) التحلل أسرع في العينة التي فيها MnO₂؛ فقد تجمع فيها 30 mL خلال أول 20 s، مقابل 1 mL فقط في العينة دون محفز، وبلغت 48 mL بعد 60 s، في حين لم تتجاوز الأخرى 25 mL بعد 600 s. (ب) يتوقف الحجم عند 48 mL لأن H₂O₂ في العينة تحلل كله؛ فكمية O₂ تحددها كمية H₂O₂، والمحفز لا يزيد عدد النواتج. لذا يُتوقع أن يصل حجم O₂ في العينة دون محفز إلى 48 mL أيضًا، ولكن بعد زمن أطول بكثير. (ج) MnO₂ محفز لا يُستهلك في التفاعل ولا يُعد من المواد المتفاعلة أو الناتجة، فيبقى بكميته نفسها ويستمر في تسريع تحلل جزيئات H₂O₂ واحدة بعد أخرى؛ لذا تكفي كمية صغيرة منه.', '["التحلل أسرع بوجود MnO₂ مع قيم من الجدول","توقف الحجم لاستهلاك H₂O₂ كله؛ المحفز لا يزيد النواتج","الحجم النهائي دون محفز 48 mL بعد زمن أطول","المحفز لا يُستهلك فيعمل مرة بعد أخرى"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد العينة الأسرع مع الاستدلال بالقيم","marks":1},{"element":"تفسير توقف الحجم عند 48 mL","marks":1},{"element":"توقع الحجم النهائي دون محفز","marks":1},{"element":"تفسير كفاية الكمية الصغيرة من المحفز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد العينة الأسرع بقيم صحيحة، ويفسر توقف الحجم بنفاد H₂O₂ وأن المحفز لا يزيد النواتج، ويتوقع 48 mL بعد زمن أطول، ويفسر كفاية الكمية الصغيرة بعدم استهلاك المحفز."},{"level":"2–3 درجات","description":"يجيب عن معظم الأجزاء مع نقص في الاستدلال بالقيم أو في أحد التفسيرات."},{"level":"1 درجة","description":"يحدد العينة الأسرع فقط، أو يذكر أن المحفز لا يُستهلك دون ربطه بالبيانات."},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة."}]'::jsonb, '["توقع أن يبقى الحجم النهائي للعينة دون محفز أقل من 48 mL دائمًا.","الاعتقاد أن المحفز يزيد كمية الأكسجين الناتجة.","تفسير توقف الحجم بنفاد MnO₂ أو استهلاكه."]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.062Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) القول خطأ؛ فالمحفز لا يزيد عدد النواتج، وكمية الأكسجين النهائية تحددها كمية H₂O₂ وحدها؛ وما قد تغيره زيادة المحفز هو سرعة الوصول إلى هذه الكمية. (ب) نأخذ حجمين متساويين من محلول H₂O₂ نفسه في وعاءين. نزن كتلة معلومة من MnO₂ ونضيفها إلى أحدهما، ونترك الآخر دون محفز. نجمع الأكسجين الناتج من كل وعاء ونقيس حجمه الكلي والزمن اللازم. بعد انتهاء التفاعل نفصل MnO₂ بالترشيح ونجففه ونزنه. النتيجة المتوقعة: حجم الأكسجين الكلي متساوٍ في الوعاءين (لكنه أسرع بوجود المحفز)، وكتلة MnO₂ بعد التفاعل تساوي كتلته قبله.', '["الحكم بخطأ القول مع التعليل","تجربة بعينتين متساويتين إحداهما بمحفز","قياس حجم O₂ الكلي في الحالتين","وزن MnO₂ قبل التفاعل وبعده (بعد الترشيح والتجفيف)"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم القول","marks":1},{"element":"تصميم المقارنة بعينتين متساويتين","marks":1},{"element":"قياس O₂ وتفسير النتيجة","marks":1},{"element":"وزن المحفز قبل وبعد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يقوّم القول معللًا ويصف تجربة كاملة تثبت الأمرين مع النتائج المتوقعة"},{"level":"2–3 درجات","description":"يقوّم القول ويصف تجربة تثبت أحد الأمرين فقط"},{"level":"1 درجة","description":"يقوّم القول دون تجربة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الموافقة على أن زيادة المحفز تزيد النواتج","وزن المحفز دون تجفيفه بعد الترشيح","عدم استعمال عينة مقارنة دون محفز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-11-04T12:15:46.062Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المادة المتفاعلة تُستهلك في التفاعل فتقل كميتها، أما المحفز فلا يُستهلك ويبقى بكميته نفسها. (ب) المادة المتفاعلة تُكتب في الطرف الأيسر من المعادلة، أما المحفز فلا يُكتب ضمن المتفاعلات ولا النواتج. (ج) زيادة كمية المادة المتفاعلة (المحددة للتفاعل) تزيد كمية النواتج، أما المحفز فلا يزيد عدد النواتج وإنما يزيد سرعة تكونها.', '["المتفاعل يُستهلك والمحفز لا يُستهلك","المتفاعل يُكتب في المعادلة والمحفز لا يُكتب ضمن المتفاعلات أو النواتج","زيادة المتفاعل تزيد النواتج، والمحفز يزيد السرعة فقط"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الاستهلاك","marks":1},{"element":"المقارنة في المعادلة","marks":1},{"element":"المقارنة في كمية النواتج","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يقارن صحيحًا في الجوانب الثلاثة"},{"level":"2 درجتان","description":"يقارن صحيحًا في جانبين"},{"level":"1 درجة","description":"يقارن صحيحًا في جانب واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المحفز يُستهلك ببطء","كتابة المحفز ضمن المتفاعلات","القول إن المحفز يزيد كمية النواتج"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-04T12:15:46.062Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
