select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'درجة حرارة الجسم الطبيعية 37°C تقريبًا، وقد تختلف قليلًا باختلاف العمر والجنس والوقت ومستوى النشاط.', '["هذه درجة حرارة الغرفة تقريبًا، لا درجة حرارة الجسم.","هذه أقل من درجة حرارة الجسم الطبيعية بكثير، وتدل على انخفاض شديد في حرارته.","هذه درجة حرارة مرتفعة جدًا تتجاوز النطاق الطبيعي للجسم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 2, 1, 'يُهضم الطعام لإنتاج الطاقة التي تُخزَّن في جزيئات ATP، وعند الحاجة يتحول ATP إلى ADP ومجموعة الفوسفات Pᵢ وتتحرر طاقة تستعملها الخلايا.', '["الطاقة تظهر في طرف النواتج، فالتفاعل يحرر الطاقة لا يمتصها.","","نواتج التفاعل ADP ومجموعة الفوسفات وطاقة، وليس إنزيمًا.","التفاعل يحرر طاقة، فهو من التفاعلات التي تسخّن الجسم لا تبرده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 3, 2, 'الإنزيمات بروتينات، والزيادة الكبيرة في الطاقة الحرارية (فوق 40°C تقريبًا) تؤدي إلى كسر التركيب البنائي للبروتينات، مما يوقف قدرتها على العمل كما ينبغي؛ فتقل سرعة التفاعل كما يبين الجزء الهابط من المنحنى.', '["زيادة الطاقة الحركية تفسر الجزء الصاعد من المنحنى فقط؛ وبعد 40°C ينخفض المنحنى.","طاقة التنشيط لا تزداد بارتفاع درجة الحرارة؛ والسبب تلف التركيب البنائي للإنزيم البروتيني.","","المنحنى ينخفض بوضوح بعد 40°C، فالإنزيم يتأثر بالحرارة المرتفعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 4, 0, 'في الجزء الصاعد من المنحنى تسبب الطاقة الحرارية زيادة الطاقة الحركية للجسيمات، فتزداد التصادمات بين الإنزيم والجزيء الذي يحفز تفاعله، فتزداد سرعة التفاعل حتى تبلغ أقصاها قرب 37°C.', '["","الإنزيم محفز لا يُستهلك في التفاعل.","ارتفاع الحرارة لا يكوّن إنزيمات جديدة؛ وإنما يزيد طاقة الجسيمات الموجودة.","نوع التفاعل لا يتغير بتغير درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 5, 2, 'زيادة درجة الحرارة ليست دائمًا طريقة عملية؛ لأن ذلك قد يضر بالخلية الحية أو يقتلها. والإنزيمات محفزات تجعل التفاعلات تحدث بالسرعة الكافية للحفاظ على الحياة عند درجة الحرارة الطبيعية للجسم (37°C تقريبًا).', '["الإنزيمات محفزات تسرّع التفاعلات عند درجة حرارة الجسم الطبيعية دون رفعها.","الإنزيم محفز لا يزيد كمية النواتج، وإنما يزيد سرعة تكونها.","","رفع درجة الحرارة يسرّع التفاعلات عمومًا، لكنه يضر الخلية الحية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 6, 0, 'عند انخفاض درجة حرارة الجسم يبدأ المهاد بالعمليات التي تزيد تحرير الطاقة الحرارية؛ فالقشعريرة تقلصات سريعة للعضلات نتيجة التفاعلات الكيميائية التي تطلق الطاقة الحرارية.', '["","القشعريرة تزيد التفاعلات الكيميائية التي تطلق الحرارة ولا تقللها.","توسع الأوعية القريبة من الجلد استجابة لارتفاع حرارة الجسم لزيادة فقد الحرارة.","التعرق استجابة لارتفاع درجة الحرارة، ويؤدي إلى تبريد الجسم لا تدفئته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-04T12:15:46.063Z"}'::jsonb),
('mcq', 7, 1, 'هذه العمليات تزيد انتقال الطاقة الحرارية إلى البيئة، فتحافظ على درجة حرارة الجسم قرب 37°C؛ وهي الدرجة التي تكون فيها الإنزيمات أكثر كفاءة، فتحدث التفاعلات بالسرعة المثلى، أما خارج هذا النطاق فتصبح سرعة التفاعل أبطأ.', '["التعرق وتوسع الأوعية يزيدان انتقال الحرارة إلى البيئة، فيبردان الجسم ولا يرفعان حرارته.","","الهدف المحافظة على 37°C تقريبًا، لا خفض الحرارة كثيرًا؛ فالانخفاض الكبير يبطئ التفاعلات الحيوية.","هذه الاستجابات تنظم درجة الحرارة، ولا تهدف إلى زيادة إنتاج ATP."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-11-04T12:15:46.064Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) تزداد سرعة التفاعل بارتفاع درجة الحرارة حتى تبلغ أقصاها قرب 37°C، ثم تنخفض بسرعة بعد 40°C تقريبًا حتى تقترب من الصفر عند 60°C. (ب) في الجزء الصاعد تزيد الطاقة الحرارية الطاقة الحركية للجسيمات فتزداد التصادمات بين الإنزيم والجزيء، فتزداد السرعة. (ج) في الجزء الهابط تؤدي الزيادة الكبيرة في الطاقة الحرارية إلى كسر التركيب البنائي للإنزيم (البروتين)، فيتوقف عن العمل كما ينبغي وتقل السرعة. (د) درجة الحرارة المثلى قريبة من درجة حرارة الجسم الطبيعية 37°C.', '["وصف المنحنى: صعود ثم أقصى قيمة قرب 37°C ثم هبوط","الصعود: زيادة الطاقة الحركية والتصادمات بين الإنزيم والجزيء","الهبوط: كسر التركيب البنائي للإنزيم البروتيني","الدرجة المثلى قرب 37°C"]'::jsonb, '[]'::jsonb, '[{"element":"وصف المنحنى","marks":1},{"element":"تفسير الصعود","marks":1},{"element":"تفسير الهبوط","marks":1},{"element":"الدرجة المثلى","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يصف المنحنى ويفسر جزأيه ويحدد الدرجة المثلى"},{"level":"2–3 درجات","description":"يصف المنحنى ويفسر أحد جزأيه فقط، أو يغفل الدرجة المثلى"},{"level":"1 درجة","description":"يصف المنحنى دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير الهبوط بزيادة طاقة التنشيط","القول إن الإنزيم يُستهلك بارتفاع الحرارة","عدّ 60°C الدرجة المثلى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-11-04T12:15:46.064Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يقوم المهاد، وهو جزء من الدماغ، بتنظيم درجة حرارة الجسم عن طريق نظام التغذية الراجعة المعقد؛ إذ يحافظ على التوازن بين الطاقة الحرارية الصادرة عن التفاعلات الكيميائية داخل الجسم والطاقة الحرارية المتبادلة بين الجسم والبيئة. (ب) عند انخفاض الحرارة: القشعريرة (تقلصات سريعة للعضلات نتيجة تفاعلات تطلق الطاقة الحرارية)، والحد من تدفق الدم إلى الجلد للحفاظ على الحرارة. (ج) عند ارتفاعها: التعرق، وتوسع الأوعية الدموية القريبة من سطح الجلد وتمددها، مع زيادة عمل القلب والرئة؛ فيزداد انتقال الحرارة إلى البيئة. وبذلك تبقى الحرارة قرب 37°C حيث تكون الإنزيمات أكفأ.', '["المهاد ينظم الحرارة بالتغذية الراجعة","التوازن بين حرارة التفاعلات والحرارة المتبادلة مع البيئة","استجابتان للبرد: القشعريرة وتقليل تدفق الدم إلى الجلد","استجابتان للحر: التعرق وتوسع الأوعية القريبة من الجلد"]'::jsonb, '[]'::jsonb, '[{"element":"المهاد وطريقة عمله","marks":1},{"element":"التوازن الحراري","marks":1},{"element":"استجابتا الانخفاض","marks":1},{"element":"استجابتا الارتفاع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحدد المهاد وطريقة عمله ويذكر استجابتين صحيحتين لكل حالة"},{"level":"2–3 درجات","description":"يذكر الاستجابات صحيحة دون شرح دور المهاد، أو يخلط بين استجابات الحالتين"},{"level":"1 درجة","description":"يذكر استجابة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسب التنظيم إلى القلب بدل المهاد","عدّ التعرق استجابة للبرد","عدّ توسع الأوعية الجلدية استجابة لانخفاض الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-04T12:15:46.064Z"}'::jsonb),
('essay', 3, null::int, null, null, 'ارتفاع الحرارة يزيد الطاقة الحركية للجسيمات، فيزيد التصادمات بين الإنزيمات والجزيئات، وهذا وحده يميل إلى زيادة سرعة التفاعلات. لكن الإنزيمات بروتينات تعمل بأعلى كفاءة قرب 37°C، والزيادة الكبيرة في الطاقة الحرارية (فوق 40°C تقريبًا) تؤدي إلى كسر تركيبها البنائي، فتفقد قدرتها على العمل كما ينبغي. وبما أن التفاعلات الحيوية لا تحدث بالسرعة التي تلبي احتياجات الجسم دون الإنزيمات، يكون الأثر الغالب هو تلف الإنزيمات، فتصبح سرعة التفاعلات أبطأ وتختل وظائف الجسم.', '["زيادة الطاقة الحركية تميل إلى زيادة السرعة","الحرارة فوق 40°C تكسر التركيب البنائي للإنزيمات","الأثر الغالب: تباطؤ التفاعلات الحيوية لتلف الإنزيمات"]'::jsonb, '[]'::jsonb, '[{"element":"أثر الحرارة في الطاقة الحركية","marks":1},{"element":"أثر الحرارة في الإنزيمات","marks":1},{"element":"تحديد الأثر الغالب مع التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"يفرق بين الأثرين ويحدد الأثر الغالب معللًا"},{"level":"2 درجتان","description":"يذكر الأثرين دون تحديد الغالب، أو يحدده دون تعليل"},{"level":"1 درجة","description":"يذكر أثرًا واحدًا فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التفاعلات الحيوية تزداد سرعتها دائمًا بارتفاع الحرارة","إهمال الطبيعة البروتينية للإنزيم","تفسير التباطؤ بزيادة طاقة التنشيط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-11-04T12:15:46.065Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K22-C2-L2-O14') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, images, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K22-C2-L3-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.images::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'في التفاعل aA → bB، إذا كان تفاعل المادة A من الرتبة الثالثة، فما معادلة قانون سرعة التفاعل؟', null, null, '["R = k[A]ᵃ","R = 3k[A]","R = k[A]³","R = k[B]³"]'::jsonb, 'تطبيق', 'كتابة قانون السرعة', 'سهل', 'الكتاب ص 66 — مسائل تدريبية (س18)'),
('mcq', 2, 'في التفاعل 2NO(g) + O₂(g) → 2NO₂(g)، وُجد تجريبيًّا أن التفاعل من الرتبة الأولى للأكسجين، وأن الرتبة الكلية للتفاعل هي الثالثة. ما قانون سرعة التفاعل؟', null, null, '["R = k[NO]²[O₂]","R = k[NO][O₂]²","R = k[NO]²[O₂]²","R = k[NO₂]²"]'::jsonb, 'تطبيق', 'كتابة قانون السرعة من الرتبة الكلية', 'متوسط', 'الكتاب ص 66 — مسائل تدريبية (س19)'),
('mcq', 3, 'للتفاعل 2NO(g) + 2H₂(g) → N₂(g) + 2H₂O(g) دلت البيانات التجريبية على أنه من الرتبة الثانية في NO ومن الرتبة الأولى في H₂. أي معادلة تمثل قانون سرعته؟', null, null, '["R = k[NO]²[H₂]²","R = k[NO][H₂]²","R = k[N₂][H₂O]²","R = k[NO]²[H₂]"]'::jsonb, 'تطبيق', 'كتابة قانون السرعة', 'متوسط', 'الكتاب ص 64–65 — تفاعل NO مع H₂'),
('mcq', 4, 'يبين المنحنى الآتي العلاقة بين السرعة الابتدائية لتحلل فوق أكسيد الهيدروجين وتركيزه. أي معادلة تمثل قانون سرعة هذا التحلل؟', null, '[{"src":"qimg/chem22/c2-l3-h2o2-line.svg","alt":"منحنى بياني لتحلل فوق أكسيد الهيدروجين H₂O₂: المحور الأفقي تركيز [H₂O₂] بوحدة mol/L من 0 إلى 3.0، والمحور الرأسي السرعة الابتدائية R بوحدة (× 10⁻⁶ mol/L·s) من 0 إلى 6. العلاقة خط مستقيم يبدأ من نقطة الأصل، وعليه نقاط مُعلَّمة: عند 0.5 mol/L تكون R = 1.0 × 10⁻⁶ mol/L·s، وعند 1.0 mol/L تكون 2.0 × 10⁻⁶، وعند 1.5 mol/L تكون 3.0 × 10⁻⁶، وعند 2.0 mol/L تكون 4.0 × 10⁻⁶، وعند 2.5 mol/L تكون 5.0 × 10⁻⁶ mol/L·s."}]'::jsonb, '["R = k[H₂O₂]²","R = k[H₂O₂]","R = k[H₂O₂]⁰","R = k[H₂O][O₂]"]'::jsonb, 'تطبيق', 'كتابة قانون السرعة من منحنى', 'متوسط', 'الكتاب ص 64 — الشكل 14-2 قوانين سرعة التفاعل من الرتبة الأولى'),
('mcq', 5, 'لماذا لا تُكتب أسس التراكيز في قانون سرعة التفاعل بأخذها من معاملات المعادلة الكيميائية الموزونة؟', null, null, '["لأن معاملات المعادلة الموزونة تتغير بتغير درجة الحرارة","لأن المعاملات تخص المواد الناتجة وحدها دون المتفاعلة","لأن رتب المواد المتفاعلة لا تساوي بالضرورة معاملاتها، فتحدد تجريبيًّا","لأن قانون السرعة لا يتضمن تراكيز المواد المتفاعلة أصلًا"]'::jsonb, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 63–64 — كتابة قوانين سرعة التفاعلات'),
('mcq', 6, 'في المنحنى الآتي تمثل المنحنيات (س) و(ص) و(ع) العلاقة بين السرعة الابتدائية وتركيز المادة المتفاعلة A في ثلاثة تفاعلات مختلفة. وقد وُجد أن تفاعل A في المنحنى (ع) من الرتبة الثانية. ما قانون سرعة هذا التفاعل؟', null, '[{"src":"qimg/chem22/c2-l3-three-curves.svg","alt":"منحنى بياني محوره الأفقي تركيز المادة المتفاعلة [A] بوحدة mol/L، ومحوره الرأسي السرعة الابتدائية R، بلا أرقام على المحورين. فيه ثلاثة منحنيات: (س) خط أفقي ثابت الارتفاع لا تتغير فيه السرعة مهما تغير التركيز؛ (ص) خط مستقيم يبدأ من نقطة الأصل وتزداد فيه السرعة بانتظام مع التركيز؛ (ع) منحنى يبدأ من نقطة الأصل ويتقوس إلى أعلى، فتزداد فيه السرعة ببطء عند التراكيز المنخفضة ثم بسرعة متزايدة عند التراكيز العالية."}]'::jsonb, '["R = k[A]","R = k[A]²","R = 2k[A]","R = k[A]³"]'::jsonb, 'تطبيق', 'كتابة قانون السرعة', 'سهل', 'الكتاب ص 64 — قوانين سرعة التفاعل لرتب أخرى'),
('mcq', 7, 'تفاعل بين المادتين A وB الرتبة الكلية له ثالثة، ووُجد تجريبيًّا أنه من الرتبة الأولى للمادة A. ما قانون سرعة التفاعل؟', null, null, '["R = k[A][B]³","R = k[A]³[B]","R = k[A][B]","R = k[A][B]²"]'::jsonb, 'تحليل', 'استنتاج رتبة مجهولة وكتابة القانون', 'صعب', 'الكتاب ص 65 — الرتبة الكلية مجموع الأسس'),
('essay', 1, 'للتفاعل العام aA + bB → نواتج، وُجد تجريبيًّا أنه من الرتبة الثانية للمادة A ومن الرتبة الأولى للمادة B.
(أ) اكتب قانون سرعة التفاعل.
(ب) ما الرتبة الكلية للتفاعل؟
(ج) كتب طالب القانون على الصورة R = k[A]ᵃ[B]ᵇ؛ بيّن خطأه.', null, null, null, 'تطبيق', 'كتابة قانون السرعة وتعليل', 'متوسط', 'الكتاب ص 64–66 — القانون العام لسرعة التفاعل'),
('essay', 2, 'اكتب معادلتي قانون سرعة التفاعل اللتين تظهران الفرق بين تفاعل من الرتبة الأولى وتفاعل من الرتبة الثانية لمادة متفاعلة واحدة A، ثم وضّح الفرق بينهما من حيث أثر مضاعفة [A] في السرعة.', null, null, null, 'فهم', 'كتابة ومقارنة', 'سهل', 'الكتاب ص 66 — التقويم 2-3 (س23)'),
('essay', 3, 'للتفاعل aA + bB + cD → نواتج، دلت البيانات التجريبية على أن التفاعل من الرتبة الأولى للمادة A، ومن الرتبة الثانية للمادة B، وأن رتبته للمادة D تساوي صفرًا.
(أ) اكتب قانون السرعة بالصورة العامة بالأسس، ثم في أبسط صورة.
(ب) احسب الرتبة الكلية.
(ج) فسّر غياب [D] من القانون في صورته المبسطة، وهل يعني ذلك أن D لا تشترك في التفاعل؟', null, null, null, 'تحليل', 'كتابة قانون السرعة وتحليله', 'صعب', 'الكتاب ص 66 — مسائل تدريبية (س20، ملاحظة الأس صفر)')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K22-C2-L3-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'قانون السرعة يساوي ثابت السرعة مضروبًا في تركيز المادة المتفاعلة مرفوعًا إلى رتبتها؛ والرتبة 3، فيكون R = k[A]³.', '["الأس في قانون السرعة هو الرتبة المحددة تجريبيًّا (3)، وليس المعامل a في المعادلة الموزونة.","الرتبة تظهر أسًّا لتركيز المادة المتفاعلة، لا عاملًا يُضرب في ثابت السرعة.","","قانون السرعة يُكتب بدلالة تراكيز المواد المتفاعلة (A)، وB مادة ناتجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.065Z"}'::jsonb),
('mcq', 2, 0, 'رتبة O₂ تساوي 1، والرتبة الكلية 3، فرتبة NO = 3 − 1 = 2؛ لذا قانون السرعة R = k[NO]²[O₂].', '["","جعل رتبة O₂ ثانية، والمعطى أنها أولى؛ فتكون رتبة NO هي 3 − 1 = 2.","مجموع الأسس هنا 4، والرتبة الكلية المعطاة 3.","قانون السرعة يُكتب بدلالة تراكيز المواد المتفاعلة لا المادة الناتجة NO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-11-04T12:15:46.065Z"}'::jsonb),
('mcq', 3, 3, 'تركيز NO يُرفع إلى الأس 2 وتركيز H₂ إلى الأس 1، فقانون السرعة R = k[NO]²[H₂]، والرتبة الكلية 3.', '["أخذ الأسين من معاملات المعادلة الموزونة (2 و2)، والرتبة في H₂ أولى؛ فالرتب تحدد تجريبيًّا.","عكس الرتبتين: الرتبة الثانية لـ NO لا لـ H₂.","استعمل تراكيز النواتج، وقانون السرعة يُكتب بدلالة تراكيز المتفاعلات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-11-04T12:15:46.066Z"}'::jsonb),
('mcq', 4, 1, 'العلاقة خط مستقيم يمر بنقطة الأصل؛ فمضاعفة [H₂O₂] من 1.0 إلى 2.0 mol/L تضاعف السرعة من 2.0 × 10⁻⁶ إلى 4.0 × 10⁻⁶ mol/L·s، فالتفاعل من الرتبة الأولى وقانونه R = k[H₂O₂].', '["لو كانت الرتبة الثانية لتضاعفت السرعة أربع مرات عند مضاعفة التركيز، لكنها في المنحنى تتضاعف مرتين فقط (من 1.0 × 10⁻⁶ إلى 2.0 × 10⁻⁶ عند مضاعفة التركيز من 0.5 إلى 1.0 mol/L).","","هذا قانون تفاعل لا تتغير سرعته بتغير التركيز (رتبة صفرية)، والمنحنى يبين أن السرعة تزداد بزيادة التركيز.","H₂O وO₂ ناتجا التحلل، وقانون السرعة يُكتب بدلالة تركيز المادة المتفاعلة H₂O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-04T12:15:46.066Z"}'::jsonb),
('mcq', 5, 2, 'الرتب تعبر عن تأثير التركيز في السرعة ولا تساوي المعاملات إلا إذا حدث التفاعل في خطوة واحدة، وهذا غير محتمل غالبًا؛ لذلك يحدد قانون السرعة تجريبيًّا.', '["معاملات المعادلة الموزونة ثابتة لا تتغير بتغير درجة الحرارة.","المعادلة الموزونة فيها معاملات للمتفاعلات والنواتج معًا.","","قانون السرعة يربط السرعة بتراكيز المواد المتفاعلة مرفوعة لرتبها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-11-04T12:15:46.066Z"}'::jsonb),
('mcq', 6, 1, 'الرتبة الثانية تعني رفع [A] إلى الأس 2، فيكون R = k[A]²؛ ولذلك يتقوس المنحنى (ع) إلى أعلى، إذ تتضاعف السرعة أربع مرات عند مضاعفة التركيز.', '["هذا قانون تفاعل من الرتبة الأولى، وهو ما يمثله المستقيم (ص).","","الرتبة تُكتب أسًّا للتركيز، لا عاملًا يضرب في k.","الأس 3 يعني أن التفاعل من الرتبة الثالثة للمادة A، والمعطى أنه من الرتبة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-11-04T12:15:46.066Z"}'::jsonb),
('mcq', 7, 3, 'الرتبة الكلية مجموع الرتب: 1 + n = 3، فـ n = 2، ويكون القانون R = k[A][B]².', '["مجموع الأسس هنا 4، والرتبة الكلية 3، فرتبة B = 3 − 1 = 2.","جعل رتبة A ثالثة، والمعطى أنها أولى.","مجموع الأسس هنا 2، أي رتبة كلية ثانية لا ثالثة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-04T12:15:46.067Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) R = k[A]²[B].
(ب) الرتبة الكلية = 2 + 1 = 3، أي أن التفاعل من الرتبة الثالثة.
(ج) أخطأ الطالب لأنه جعل الأسين معاملي المعادلة a وb، والأسس في قانون السرعة هي رتب المواد المتفاعلة التي تحدد تجريبيًّا، ولا تساوي المعاملات بالضرورة.', '["R = k[A]²[B]","الرتبة الكلية 3 (مجموع الأسس)","الأسس رتب تحدد تجريبيًّا لا معاملات المعادلة"]'::jsonb, '[]'::jsonb, '[{"element":"كتابة قانون السرعة صحيحًا","marks":2},{"element":"حساب الرتبة الكلية","marks":1},{"element":"بيان خطأ الطالب مع التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"قانون صحيح ورتبة كلية صحيحة وتعليل كامل لخطأ الطالب"},{"level":"3–4 درجات","description":"قانون صحيح مع نقص في الرتبة الكلية أو التعليل"},{"level":"1–2 درجة","description":"جزء واحد صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة R = k[A]²[B]² أو تبديل الرتبتين","عدّ الرتبة الكلية 2 بدل 3","القول إن الأسس تساوي المعاملات دائمًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-11-04T12:15:46.067Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الرتبة الأولى: R = k[A]، والرتبة الثانية: R = k[A]². في الرتبة الأولى تتناسب السرعة طرديًّا مع [A]، فإذا تضاعف التركيز مرتين تضاعفت السرعة مرتين (2¹ = 2). وفي الرتبة الثانية تتناسب السرعة مع مربع التركيز، فإذا تضاعف التركيز مرتين تضاعفت السرعة أربع مرات (2² = 4).', '["R = k[A] للرتبة الأولى","R = k[A]² للرتبة الثانية","مضاعفة التركيز تضاعف السرعة مرتين في الأولى","وأربع مرات في الثانية"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة الرتبة الأولى","marks":1},{"element":"معادلة الرتبة الثانية","marks":1},{"element":"أثر المضاعفة في الرتبة الأولى","marks":1},{"element":"أثر المضاعفة في الرتبة الثانية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلتان صحيحتان وأثر المضاعفة صحيح في الحالتين"},{"level":"2–3 درجات","description":"المعادلتان صحيحتان مع خطأ أو نقص في توضيح الأثر"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة R = 2k[A] للرتبة الثانية","القول إن السرعة تتضاعف مرتين في الحالتين","الخلط بين الرتبة ومعامل A في المعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-04T12:15:46.067Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) R = k[A]¹[B]²[D]⁰، وبما أن أي عدد مرفوع إلى الأس صفر يساوي 1 فإن [D]⁰ = 1، فيصبح القانون R = k[A][B]².
(ب) الرتبة الكلية = 1 + 2 + 0 = 3.
(ج) يغيب [D] لأن رتبته صفر، أي أن تغيير تركيزه لا يغير السرعة الابتدائية. ولا يعني ذلك أن D لا تشترك في التفاعل؛ فهي مادة متفاعلة في المعادلة وتُستهلك، لكن تركيزها لا يؤثر في سرعة التفاعل.', '["R = k[A][B]²[D]⁰","[D]⁰ = 1 فيصبح R = k[A][B]²","الرتبة الكلية 3","الرتبة الصفرية: تغيير [D] لا يغير السرعة","D تبقى مادة متفاعلة"]'::jsonb, '["كتابة كل تركيز مرفوعًا إلى رتبته: R = k[A]¹[B]²[D]⁰","تبسيط [D]⁰ = 1: R = k[A][B]²","جمع الرتب: 1 + 2 + 0 = 3"]'::jsonb, '[{"element":"القانون بالأسس","marks":1},{"element":"التبسيط","marks":1},{"element":"الرتبة الكلية","marks":1},{"element":"تفسير غياب [D]","marks":1},{"element":"بيان أن D تبقى مادة متفاعلة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"القانون والتبسيط والرتبة صحيحة مع تفسير كامل"},{"level":"3–4 درجات","description":"القانون صحيح مع نقص في التفسير أو الرتبة"},{"level":"1–2 درجة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إدخال [D] بالأس 1","جعل الرتبة الكلية 2 بإهمال B أو 4 بعدّ D","القول إن D ليست مادة متفاعلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-04T12:15:46.067Z"}'::jsonb)
