from (values
('mcq', 1, 1, 'في المحاولتين 2 و3 يبقى [A] ثابتًا ويتضاعف [B] من 0.100 إلى 0.200 M، فتزداد السرعة من 4.00 × 10⁻³ إلى 16.00 × 10⁻³، أي أربع مرات؛ ولأن 2ⁿ = 4 فإن n = 2، أي أن التفاعل من الرتبة الثانية بالنسبة لـ B.', '["عند مضاعفة [B] (المحاولتان 2 و3) تضاعفت السرعة أربع مرات لا مرتين.","","خلط بين نسبة تغير السرعة (4) والرتبة؛ فالرتبة n تحقق 2ⁿ = 4.","الرتبة الثالثة هي الرتبة الكلية للتفاعل (1 + 2)، لا رتبة B وحدها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-04T12:15:46.068Z"}'::jsonb),
('mcq', 2, 2, 'من المحاولتين 1 و2: تضاعف [A] وبقيت السرعة 2.00 × 10⁻³، فـ 2ᵐ = 1 ومنه m = 0. ومن المحاولتين 2 و3: تضاعف [B] فتضاعفت السرعة مرتين، فـ n = 1. إذن R = k[A]⁰[B] = k[B].', '["مضاعفة [A] (المحاولتان 1 و2) لم تغير السرعة، فرتبة A صفر لا واحد.","السرعة لم تتغير بتغير [A]، وتضاعفت بمضاعفة [B]؛ فالتركيز المؤثر هو [B].","","مضاعفة [B] ضاعفت السرعة مرتين فقط، فرتبة B أولى لا ثانية، ورتبة A صفر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-04T12:15:46.068Z"}'::jsonb),
('mcq', 3, 0, 'تضاعف التركيز من 0.012 M إلى 0.024 M فتضاعفت السرعة من 2.5 × 10⁻⁶ إلى 5.0 × 10⁻⁶ mol/L·s، أي 2ᵐ = 2 ومنه m = 1: التفاعل من الرتبة الأولى.', '["","لو كانت الرتبة الثانية لتضاعفت السرعة أربع مرات عند مضاعفة التركيز، لكنها تضاعفت مرتين.","السرعة تغيرت بتغير التركيز، ففي الرتبة الصفرية لا تتغير السرعة.","لا تؤيدها البيانات؛ فالرتبة الثالثة تعني أن السرعة تزداد ثماني مرات عند مضاعفة التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-11-04T12:15:46.068Z"}'::jsonb),
('mcq', 4, 3, 'عند مضاعفة [A] من 0.10 إلى 0.20 mol/L زادت السرعة من 1.0 × 10⁻³ إلى 4.0 × 10⁻³ mol/L·s (أربع مرات)، فـ 2ᵐ = 4 ومنه m = 2؛ ويؤكد ذلك أن مضاعفة التركيز ثلاث مرات رفعت السرعة تسع مرات (3² = 9). فالتفاعل من الرتبة الثانية.', '["في الرتبة الأولى تتضاعف السرعة مرتين عند مضاعفة التركيز، وهنا زادت من 1.0 × 10⁻³ إلى 4.0 × 10⁻³ أي أربع مرات.","خلط بين نسبة تغير السرعة (4) والرتبة؛ والصحيح 2ᵐ = 4 ومنه m = 2.","مضاعفة التركيز ثلاث مرات (من 0.10 إلى 0.30) رفعت السرعة تسع مرات، و3ᵐ = 9 تعطي m = 2 لا 3.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-11-04T12:15:46.068Z"}'::jsonb),
('mcq', 5, 1, 'من المحاولتين 1 و2: [X] زاد ثلاث مرات فزادت السرعة ثلاث مرات (3ᵐ = 3، m = 1). ومن المحاولتين 2 و3: [Y] تضاعف فزادت السرعة من 9.0 × 10⁻⁴ إلى 3.6 × 10⁻³ أي أربع مرات (2ⁿ = 4، n = 2). الرتبة الكلية = 1 + 2 = 3، أي الثالثة.', '["عدّ التفاعل من الرتبة الأولى لكلتا المادتين، لكن مضاعفة [Y] رفعت السرعة أربع مرات، فرتبة Y هي 2.","","جعل رتبة X ثانية؛ لكن زيادة [X] ثلاث مرات رفعت السرعة ثلاث مرات فقط، فرتبة X هي 1.","جمع نسبتي تغير السرعة (3 + 4) بدل جمع الرتب (1 + 2)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-11-04T12:15:46.069Z"}'::jsonb),
('mcq', 6, 3, 'تحدد رتبة مادة بمقارنة محاولتين يتغير فيهما تركيزها وحده ويبقى تركيز المادة الأخرى ثابتًا؛ وفي المحاولتين 2 و3 يبقى [A] = 0.200 M ثابتًا ويتضاعف [B].', '["في هاتين المحاولتين [B] ثابت ويتغير [A]، فهما تحددان رتبة A لا رتبة B.","تغير فيهما [A] و[B] معًا، فلا يمكن نسبة تغير السرعة إلى B وحده.","ثبات k لا يكفي؛ يجب أن يتغير تركيز مادة واحدة فقط ويبقى الآخر ثابتًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (39%)"}],"at":"2026-11-04T12:15:46.069Z"}'::jsonb),
('mcq', 7, 0, 'في الرتبة الأولى R = k[A] تتناسب السرعة طرديًّا مع التركيز، فيكون المنحنى خطًّا مستقيمًا يمر بنقطة الأصل، وهو المنحنى (ص).', '["","السرعة في (س) ثابتة لا تتغير بتغير التركيز، وهذا يمثل الرتبة الصفرية.","المنحنى (ع) يتقوس إلى أعلى، فتزداد السرعة أسرع من التركيز، وهذا يمثل الرتبة الثانية.","المنحنى (ع) ليس خطًّا مستقيمًا؛ فالسرعة فيه لا تتناسب طرديًّا مع التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-11-04T12:15:46.069Z"}'::jsonb),
('essay', 1, null::int, null, null, 'رتبة A: من المحاولتين 1 و2 ([B] ثابت = 0.100 M)، تضاعف [A] فتضاعفت السرعة من 2.00 × 10⁻³ إلى 4.00 × 10⁻³ mol/L·s، فـ 2ᵐ = 2 ومنه m = 1.
رتبة B: من المحاولتين 2 و3 ([A] ثابت = 0.200 M)، تضاعف [B] فزادت السرعة من 4.00 × 10⁻³ إلى 16.00 × 10⁻³ أي أربع مرات، فـ 2ⁿ = 4 ومنه n = 2.
قانون السرعة: R = k[A][B]²، والرتبة الكلية = 1 + 2 = 3.', '["اختيار المحاولتين 1 و2 لتحديد رتبة A","m = 1","اختيار المحاولتين 2 و3 لتحديد رتبة B","n = 2","R = k[A][B]²","الرتبة الكلية 3"]'::jsonb, '["المحاولتان 1 و2: نسبة السرعتين = 4.00 × 10⁻³ ÷ 2.00 × 10⁻³ = 2، ونسبة [A] = 2 ← 2ᵐ = 2 ← m = 1","المحاولتان 2 و3: نسبة السرعتين = 16.00 × 10⁻³ ÷ 4.00 × 10⁻³ = 4، ونسبة [B] = 2 ← 2ⁿ = 4 ← n = 2","R = k[A]¹[B]² = k[A][B]²","الرتبة الكلية = 1 + 2 = 3"]'::jsonb, '[{"element":"تحديد رتبة A بالمقارنة الصحيحة","marks":2},{"element":"تحديد رتبة B بالمقارنة الصحيحة","marks":2},{"element":"كتابة قانون السرعة","marks":1},{"element":"الرتبة الكلية","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"الرتبتان صحيحتان بمقارنات سليمة، والقانون والرتبة الكلية صحيحان"},{"level":"3–5 درجات","description":"رتبة واحدة صحيحة أو خطأ في القانون أو الرتبة الكلية"},{"level":"1–2 درجة","description":"محاولة مقارنة صحيحة واحدة دون استنتاج كامل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة محاولتين يتغير فيهما التركيزان معًا","عدّ نسبة تغير السرعة (4) رتبةً","كتابة القانون من المعاملات a وb"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-11-04T12:15:46.069Z"}'::jsonb),
('essay', 2, null::int, null, null, 'رتبة A: المحاولتان 1 و2 ([B] ثابت = 0.010 M): تضاعف [A] من 0.020 إلى 0.040 M، فزادت السرعة من 1.2 × 10⁻⁴ إلى 4.8 × 10⁻⁴ أي أربع مرات؛ 2ᵐ = 4 ومنه m = 2.
رتبة B: المحاولتان 1 و3 ([A] ثابت = 0.020 M): زاد [B] ثلاث مرات من 0.010 إلى 0.030 M، فزادت السرعة من 1.2 × 10⁻⁴ إلى 3.6 × 10⁻⁴ أي ثلاث مرات؛ 3ⁿ = 3 ومنه n = 1.
