('mcq', 1, 2, 'ثابت سرعة التفاعل k لا يتغير مع تغير التركيز، ولكنه يتغير مع تغير درجة الحرارة؛ لذا فرفع درجة الحرارة هو الذي يغير k.', '["تغيير التركيز يغير السرعة R، لكن k لا يتغير مع تغير التركيز.","خفض التركيز يخفض السرعة، أما k فيبقى ثابتًا.","","إضافة محلول بالتركيز نفسه لا يغير التركيز ولا k."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.074Z"}'::jsonb),
('mcq', 2, 0, 'k لا يتغير مع تغير التركيز عند درجة حرارة ثابتة؛ فمضاعفة [A] تضاعف السرعة R، وتبقى قيمة k ثابتة.', '["","التي تتضاعف هي السرعة R لا ثابت السرعة k.","k لا يتغير بتغير التركيز، ولا يتناسب عكسيًّا معه.","هذا خلط بين k وأثر مضاعفة التركيز في سرعة تفاعل من الرتبة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.075Z"}'::jsonb),
('mcq', 3, 3, 'في R = k[A] يمثل ميل المستقيم قيمة k، والمستقيم T₂ أشد ميلًا؛ فقيمة k عند T₂ أكبر منها عند T₁، لأن k يتغير مع تغير درجة الحرارة.', '["لو تساوت k لتطابق المستقيمان؛ فميل المستقيم يمثل k، والمستقيمان مختلفا الميل.","المستقيم T₁ أقل ميلًا، فقيمة k عنده أصغر.","كلا المنحنيين خط مستقيم يمر بالأصل، فالرتبة أولى في الحالتين؛ الذي تغير هو k.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-11-04T12:15:46.075Z"}'::jsonb),
('mcq', 4, 1, 'تعني القيمة الكبيرة لـ k أن A يتفاعل بسرعة لتكوين B؛ لأن السرعة R = k[A] تكبر بكبر k عند التركيز نفسه.', '["العكس صحيح؛ فكلما كبرت k زادت السرعة عند التركيز نفسه.","","k مستقل عن التركيز، وقيمته الكبيرة لا تعني تركيزًا كبيرًا.","الرتبة هي أس التركيز، ولا تُستنتج من قيمة k."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-11-04T12:15:46.075Z"}'::jsonb),
('mcq', 5, 2, 'R₁ = 4.0 × 10⁻² × 0.10 = 4.0 × 10⁻³ mol/L·s، وR₂ = 6.0 × 10⁻⁴ × 0.10 = 6.0 × 10⁻⁵ mol/L·s؛ فالتفاعل (1) أسرع لأن قيمة k له أكبر.', '["القيمة الصغيرة لـ k تعني تفاعلًا أبطأ عند التركيز نفسه.","تساوي التركيزين لا يعني تساوي السرعتين؛ فالسرعة R = k[A] تعتمد على k أيضًا.","","الرتبة معطاة (الأولى لكليهما)، فالمقارنة ممكنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-11-04T12:15:46.075Z"}'::jsonb),
('mcq', 6, 3, 'k لا يتغير مع تغير التركيز، ولكنه يتغير مع تغير درجة الحرارة؛ فزيادة [A] تزيد السرعة R = k[A] ويبقى k ثابتًا ما دامت درجة الحرارة ثابتة.', '["k لا يتغير مع تغير التركيز؛ الذي يزداد هو R فقط.","k لا يتغير مع التركيز، والسرعة تزداد في تفاعل من الرتبة الأولى.","السرعة تتناسب طرديًّا مع [A] في هذا التفاعل، فتزداد بزيادته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-11-04T12:15:46.075Z"}'::jsonb),
('mcq', 7, 1, 'k = R ÷ [A]: في التجربة 1 = 2.0 × 10⁻⁴ ÷ 0.10 = 2.0 × 10⁻³ s⁻¹، وفي التجربة 2 = 4.0 × 10⁻⁴ ÷ 0.20 = 2.0 × 10⁻³ s⁻¹، وفي التجربة 3 = 4.0 × 10⁻⁴ ÷ 0.10 = 4.0 × 10⁻³ s⁻¹. إذن k ثابت عند 25°C مع تغير [A]، ويزداد عند 35°C.', '["k = R/[A] = 2.0 × 10⁻³ s⁻¹ في التجربتين 1 و2، فلم يتغير بمضاعفة [A].","","k عند 35°C = 4.0 × 10⁻³ s⁻¹، وهو أكبر من قيمته عند 25°C (2.0 × 10⁻³ s⁻¹).","k ازداد من 2.0 × 10⁻³ إلى 4.0 × 10⁻³ s⁻¹ برفع درجة الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-11-04T12:15:46.076Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ثابت سرعة التفاعل k محدد لكل تفاعل، ولا يتغير مع تغير تركيز المواد المتفاعلة، ولكنه يتغير مع تغير درجة الحرارة.
(أ) عند مضاعفة [A] عند درجة حرارة ثابتة: تتضاعف السرعة R مرتين، ويبقى k ثابتًا.
(ب) عند رفع درجة الحرارة مع ثبات [A]: تتغير قيمة k (تزداد في العادة لأن عدد الاصطدامات الفعالة يزداد)، فتزداد السرعة R عند التركيز نفسه.', '["k محدد لكل تفاعل","k لا يتغير مع التركيز","k يتغير مع درجة الحرارة","(أ) R تتضاعف وk ثابت","(ب) k يزداد فتزداد R"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن k لا يعتمد على التركيز","marks":1},{"element":"بيان أن k يعتمد على درجة الحرارة","marks":1},{"element":"الحالة (أ)","marks":1},{"element":"الحالة (ب)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل مع الحالتين صحيحتين"},{"level":"2–3 درجات","description":"توضيح صحيح لعامل واحد مع حالة واحدة"},{"level":"1 درجة","description":"عبارة صحيحة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن k يتضاعف بمضاعفة التركيز","القول إن k ثابت في جميع الظروف","الخلط بين R وk"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-11-04T12:15:46.076Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) قانون السرعة R = k[A]، فميل كل مستقيم (R ÷ [A]) يمثل ثابت سرعة التفاعل k عند درجة الحرارة تلك.
(ب) قيمة k أكبر عند T₂، لأن المستقيم T₂ أشد ميلًا؛ أي أن السرعة عنده أكبر عند أي تركيز واحد.
