from (values
('mcq', 1, 'إذا كانت رتبة المادة المتفاعلة في تفاعل كيميائي هي الأولى، فكيف تتغير سرعة التفاعل إذا تضاعف تركيز هذه المادة ثلاثة أضعاف؟', null, null, '["تزداد تسع مرات","تبقى كما هي","تنخفض إلى الثلث","تزداد ثلاث مرات"]'::jsonb, 'تطبيق', 'توقع أثر تغير التركيز', 'سهل', 'الكتاب ص 64 — ماذا قرأت؟ (الرتبة الأولى)'),
('mcq', 2, 'في التفاعل A + B → AB وُجد تجريبيًّا أن التفاعل من الرتبة الثانية للمادة A. كيف تتغير سرعة التفاعل إذا انخفض تركيز A إلى النصف وبقيت جميع الظروف الأخرى ثابتة؟', null, null, '["تنخفض إلى الربع","تنخفض إلى النصف","تزداد إلى الضعف","تزداد أربع مرات"]'::jsonb, 'تطبيق', 'توقع أثر تغير التركيز', 'متوسط', 'الكتاب ص 71 — تقويم الفصل (س47)'),
('mcq', 3, 'يبين المنحنى الآتي العلاقة بين السرعة الابتدائية لتحلل H₂O₂ وتركيزه (قيم المحور الرأسي مضروبة في 10⁻⁶). ما السرعة الابتدائية المتوقعة إذا أصبح تركيز H₂O₂ يساوي 3.0 mol/L؟', null, '[{"src":"qimg/chem22/c2-l3-h2o2-line.svg","alt":"منحنى بياني لتحلل فوق أكسيد الهيدروجين H₂O₂: المحور الأفقي تركيز [H₂O₂] بوحدة mol/L من 0 إلى 3.0، والمحور الرأسي السرعة الابتدائية R بوحدة (× 10⁻⁶ mol/L·s) من 0 إلى 6. العلاقة خط مستقيم يبدأ من نقطة الأصل، وعليه نقاط مُعلَّمة: عند 0.5 mol/L تكون R = 1.0 × 10⁻⁶ mol/L·s، وعند 1.0 mol/L تكون 2.0 × 10⁻⁶، وعند 1.5 mol/L تكون 3.0 × 10⁻⁶، وعند 2.0 mol/L تكون 4.0 × 10⁻⁶، وعند 2.5 mol/L تكون 5.0 × 10⁻⁶ mol/L·s."}]'::jsonb, '["1.2 × 10⁻⁵ mol/L·s","3.0 × 10⁻⁶ mol/L·s","6.0 × 10⁻⁶ mol/L·s","2.0 × 10⁻⁶ mol/L·s"]'::jsonb, 'تطبيق', 'توقع من منحنى', 'متوسط', 'الكتاب ص 64 — الشكل 14-2 واختبار الرسم البياني'),
('mcq', 4, 'قانون سرعة التفاعل 2NO(g) + 2H₂(g) → N₂(g) + 2H₂O(g) هو R = k[NO]²[H₂]. كيف تتغير سرعة التفاعل إذا تضاعف كل من [NO] و[H₂] مرتين معًا؟', null, null, '["تزداد أربع مرات","تزداد ثماني مرات","تزداد ست مرات","تزداد ست عشرة مرة"]'::jsonb, 'تطبيق', 'توقع أثر تغيير تركيزين', 'صعب', 'الكتاب ص 64–65 — تفاعل NO مع H₂'),
('mcq', 5, 'في المنحنى الآتي تمثل المنحنيات (س) و(ص) و(ع) العلاقة بين السرعة الابتدائية وتركيز المادة المتفاعلة A في ثلاثة تفاعلات. في أي منحنى تتضاعف السرعة أربع مرات عند مضاعفة [A] مرتين؟', null, '[{"src":"qimg/chem22/c2-l3-three-curves.svg","alt":"منحنى بياني محوره الأفقي تركيز المادة المتفاعلة [A] بوحدة mol/L، ومحوره الرأسي السرعة الابتدائية R، بلا أرقام على المحورين. فيه ثلاثة منحنيات: (س) خط أفقي ثابت الارتفاع لا تتغير فيه السرعة مهما تغير التركيز؛ (ص) خط مستقيم يبدأ من نقطة الأصل وتزداد فيه السرعة بانتظام مع التركيز؛ (ع) منحنى يبدأ من نقطة الأصل ويتقوس إلى أعلى، فتزداد فيه السرعة ببطء عند التراكيز المنخفضة ثم بسرعة متزايدة عند التراكيز العالية."}]'::jsonb, '["المنحنى (ص)","المنحنى (س)","المنحنيان (ص) و(ع) معًا","المنحنى (ع)"]'::jsonb, 'فهم', 'ربط الرتبة بالمنحنى', 'متوسط', 'الكتاب ص 64 — قوانين سرعة التفاعل لرتب أخرى'),
('mcq', 6, 'قانون سرعة تفاعل هو R = k[A]⁰[B]. إذا تضاعف تركيز A مرتين وبقي تركيز B ثابتًا، فكيف تتغير سرعة التفاعل؟', null, null, '["تتضاعف مرتين","تنخفض إلى النصف","لا تتغير","تنعدم السرعة"]'::jsonb, 'تطبيق', 'توقع أثر تغير التركيز', 'سهل', 'الكتاب ص 66 — مسائل تدريبية (س20، ملاحظة الأس صفر)'),
('mcq', 7, 'قانون سرعة تفاعل هو R = k[A][B]². ماذا يحدث لسرعة التفاعل إذا انخفض [A] إلى النصف وتضاعف [B] مرتين في الوقت نفسه؟', null, null, '["تتضاعف مرتين","لا تتغير","تزداد أربع مرات","تنخفض إلى النصف"]'::jsonb, 'تحليل', 'توقع أثر تغيير تركيزين', 'صعب', 'الكتاب ص 64–65 — القانون العام لسرعة التفاعل'),
('essay', 1, 'للتفاعل A + B → AB وُجد تجريبيًّا أنه من الرتبة الثانية للمادة A. توقع، مع التعليل بالحساب، كيف تتغير سرعة التفاعل في كل حالة مما يأتي مع بقاء الظروف الأخرى ثابتة:
(أ) انخفاض [A] إلى النصف.
(ب) زيادة [A] ثلاث مرات.', null, null, null, 'تطبيق', 'توقع مع تعليل', 'متوسط', 'الكتاب ص 71 — تقويم الفصل (س47)'),
('essay', 2, 'قانون سرعة التفاعل 2NO(g) + 2H₂(g) → N₂(g) + 2H₂O(g) هو R = k[NO]²[H₂].
(أ) كم مرة يجب أن يزداد [NO] وحده لتصبح السرعة تسعة أمثال قيمتها؟
(ب) ماذا يحدث للسرعة إذا تضاعف [NO] وانخفض [H₂] إلى النصف معًا؟
(ج) لماذا لا تتأثر السرعة بـ [H₂] كما تتأثر بـ [NO]؟', null, null, null, 'تحليل', 'توقع وتعليل', 'صعب', 'الكتاب ص 64–65 — تفاعل NO مع H₂'),
('essay', 3, 'في المنحنى الآتي تمثل المنحنيات (س) و(ص) و(ع) العلاقة بين السرعة الابتدائية وتركيز المادة A في ثلاثة تفاعلات، ورتبة التفاعل بالنسبة للمادة A فيها هي 0 و1 و2 (لا بالترتيب نفسه). لكل منحنى: حدد رتبة التفاعل بالنسبة للمادة A مع التعليل، واكتب قانون السرعة، وتوقع ما يحدث للسرعة إذا تضاعف [A] مرتين. (تذكّر أن أي عدد مرفوع إلى القوة صفر يساوي 1.)', null, '[{"src":"qimg/chem22/c2-l3-three-curves.svg","alt":"منحنى بياني محوره الأفقي تركيز المادة المتفاعلة [A] بوحدة mol/L، ومحوره الرأسي السرعة الابتدائية R، بلا أرقام على المحورين. فيه ثلاثة منحنيات: (س) خط أفقي ثابت الارتفاع لا تتغير فيه السرعة مهما تغير التركيز؛ (ص) خط مستقيم يبدأ من نقطة الأصل وتزداد فيه السرعة بانتظام مع التركيز؛ (ع) منحنى يبدأ من نقطة الأصل ويتقوس إلى أعلى، فتزداد فيه السرعة ببطء عند التراكيز المنخفضة ثم بسرعة متزايدة عند التراكيز العالية."}]'::jsonb, null, 'تحليل', 'تحليل منحنى وتوقع', 'صعب', 'الكتاب ص 64–66 — قوانين سرعة التفاعل')
) as v(type, number, stem, stimulus, images, options, tl, qk, diff, src)
