('mcq', 1, 1, 'k = R ÷ [CH₃N₂CH₃] = 2.5 × 10⁻⁶ ÷ 0.012 = 2.08 × 10⁻⁴ ≈ 2.1 × 10⁻⁴ s⁻¹ (وتعطي التجربة 2 القيمة نفسها: 5.0 × 10⁻⁶ ÷ 0.024).', '["ضرب السرعة في التركيز (2.5 × 10⁻⁶ × 0.012) بدل القسمة عليه.","","قسم التركيز على السرعة (0.012 ÷ 2.5 × 10⁻⁶)، أي عكس النسبة.","قسم على مربع التركيز كأن التفاعل من الرتبة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (48%)"}],"at":"2026-11-04T12:15:46.081Z"}'::jsonb),
('mcq', 2, 3, 'R = k[CH₃N₂CH₃] = 2.08 × 10⁻⁴ s⁻¹ × 0.048 M = 1.0 × 10⁻⁵ mol/L·s؛ أو: التركيز 0.048 M أربعة أمثال 0.012 M، فالسرعة أربعة أمثال 2.5 × 10⁻⁶ أي 1.0 × 10⁻⁵ mol/L·s.', '["عامل التفاعل كأنه من الرتبة الثانية (نسبة التركيز 4، و4² = 16).","ظن أن السرعة لا تتغير بتغير التركيز.","هذه السرعة عند 0.024 M؛ ولم يُضاعفها عند مضاعفة التركيز إلى 0.048 M.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (46%)"}],"at":"2026-11-04T12:15:46.081Z"}'::jsonb),
('mcq', 3, 0, 'k = 2.70 × 10⁻¹¹ ÷ (2.00 × 10⁻³)² = 6.75 × 10⁻⁶ L/mol·s، وR₃ = 6.75 × 10⁻⁶ × (8.00 × 10⁻³)² = 4.32 × 10⁻¹⁰ mol/L·s؛ أي أربعة أمثال سرعة المحاولة 2 لأن التركيز تضاعف (2² = 4).', '["","ضاعف السرعة مرتين فقط كأن التفاعل من الرتبة الأولى.","ضاعف السرعة ثماني مرات كأن التفاعل من الرتبة الثالثة.","افترض أن السرعة تزداد بمقدار ثابت (10.8 + 8.1)، والزيادة في الرتبة الثانية تكون بمربع نسبة التركيز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-11-04T12:15:46.081Z"}'::jsonb),
('mcq', 4, 2, 'من أي نقطة على المستقيم: k = R ÷ [H₂O₂] = 4.0 × 10⁻⁶ mol/L·s ÷ 2.0 mol/L = 2.0 × 10⁻⁶ s⁻¹.', '["قسم التركيز على السرعة، أي عكس النسبة k = R ÷ [H₂O₂].","أهمل العامل 10⁻⁶ المكتوب على المحور الرأسي.","","قسم السرعة على مربع التركيز (4.0 × 10⁻⁶ ÷ 2.0²) كأن التفاعل من الرتبة الثانية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-04T12:15:46.081Z"}'::jsonb),
('mcq', 5, 1, 'k = R ÷ [A] = 2.0 × 10⁻³ ÷ 0.050 = 0.040 s⁻¹ (وتعطي النقطة الأخرى 6.0 × 10⁻³ ÷ 0.150 القيمة نفسها)، ثم R = 0.040 × 0.25 = 1.0 × 10⁻² mol/L·s.', '["حسب k كأن التفاعل من الرتبة الثانية (R ÷ [A]²) ثم ضربه في [A]².","","قلب النسبة فحسب k = [A] ÷ R = 25 ثم ضربه في التركيز.","أهمل العامل 10⁻³ المكتوب على المحور الرأسي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-11-04T12:15:46.081Z"}'::jsonb),
('mcq', 6, 3, 'k = R ÷ [A]² = 1.0 × 10⁻³ ÷ (0.10)² = 0.10 L/mol·s (وتعطي النقطة 4.0 × 10⁻³ ÷ (0.20)² القيمة نفسها).', '["قسم السرعة على التركيز دون تربيعه، كأن التفاعل من الرتبة الأولى.","قلب النسبة: [A]² ÷ R بدل R ÷ [A]².","ضرب السرعة في مربع التركيز بدل القسمة عليه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-11-04T12:15:46.082Z"}'::jsonb),
